<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();if($_SERVER['REQUEST_METHOD']==='POST'){$q=$db->prepare('INSERT INTO automation_rules(name,event_name,conditions_json,actions_json,is_active) VALUES(?,?,?,?,?)');$q->execute([trim($_POST['name']),trim($_POST['event_name']),$_POST['conditions_json']?:'{}',$_POST['actions_json']?:'[]',isset($_POST['is_active'])?1:0]);header('Location: automation.php');exit;}$rows=$db->query('SELECT * FROM automation_rules ORDER BY id DESC')->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><title>Automation</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><h1 class="h3">Automation Rules</h1><form method="post" class="card card-body mb-4"><div class="row g-2"><div class="col-md-3"><input class="form-control" name="name" placeholder="Rule name" required></div><div class="col-md-3"><input class="form-control" name="event_name" placeholder="Event name" required></div><div class="col-md-3"><input class="form-control" name="conditions_json" value="{}" placeholder="Conditions JSON"></div><div class="col-md-3"><input class="form-control" name="actions_json" value="[]" placeholder="Actions JSON"></div></div><button class="btn btn-dark mt-3">Create Rule</button></form><table class="table bg-white"><thead><tr><th>Name</th><th>Event</th><th>Active</th><th>Last Run</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['name'])?></td><td><?=htmlspecialchars($r['event_name'])?></td><td><?=$r['is_active']?'Yes':'No'?></td><td><?=htmlspecialchars($r['last_run_at']??'Never')?></td></tr><?php endforeach;?></tbody></table></main></body></html>